void __thiscall SPELLSEL_DrawSkillLevel(int32_t pThis, int32_t nScreenX, int32_t nIconY) {
    uint16_t wszLevelBuf[16];
    char szLevelBuf[16];
    memset(wszLevelBuf, 0, 16 * sizeof(wszLevelBuf[0]));
    if (0 >= pThis) {
      return;
    }

    int32_t nTextWidth2 = 0x10;
    char* pszLevel = _itoa(pThis, szLevelBuf, 10);
    D2Lang::UTF8_ConvertToWideChar(wszLevelBuf, pszLevel, nTextWidth2);
    nTextWidth2 = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(wszLevelBuf);
    int32_t nTextWidth = D2Win::Src::D2WinFont::DRAW_text0(wszLevelBuf);
    if (nTextWidth > 0x28) {
      uint16_t* pWcharEnd;
      pWcharEnd = wszLevelBuf + nTextWidth2;
      do {
        *pWcharEnd = L'\0';
        pWcharEnd--;
        nTextWidth2 = D2Win::Src::D2WinFont::DRAW_text0(wszLevelBuf);
      } while (nTextWidth2 > 0x28);
    }

    D2Win::Src::D2WinFont::DRAW_text0(wszLevelBuf);
    D2Win::Src::D2WinFont::DRAW_text(wszLevelBuf, nScreenX + 4, nIconY - 1, 3, 0);
}

